INSERT INTO app_settings (key, value) VALUES ('routing', $cfg${"_lanes":"Tiers are fine-grained SLA buckets; the lane is what staff see. escalated = P1/P2 (+ repeat negative customers), in_queue = P3/P4, ready_to_post = POSITIVE, logged = NEUTRAL.","P1_CRITICAL":{"label":"Critical","lane":"escalated","notify_roles":["branch_lead","regional_manager","hq"],"channels":["whatsapp","email"],"respect_quiet_hours":false,"ack_sla_minutes":30,"contact_sla_minutes":120,"resolve_sla_minutes":2880,"escalation_chain":[["ops_director"],["ops_director","hq"]],"escalation_repeat_minutes":30,"create_case":true},"P2_HIGH":{"label":"High","lane":"escalated","notify_roles":["branch_lead","regional_manager","hq"],"channels":["whatsapp","email"],"respect_quiet_hours":false,"ack_sla_minutes":60,"contact_sla_minutes":240,"resolve_sla_minutes":2880,"escalation_chain":[["ops_director"]],"escalation_repeat_minutes":60,"create_case":true},"P3_MEDIUM":{"label":"Medium","lane":"in_queue","notify_roles":[],"channels":[],"respect_quiet_hours":true,"ack_sla_minutes":null,"contact_sla_minutes":null,"resolve_sla_minutes":4320,"escalation_chain":[],"create_case":true},"P4_LOW":{"label":"Low","lane":"in_queue","notify_roles":[],"channels":[],"respect_quiet_hours":true,"ack_sla_minutes":null,"contact_sla_minutes":null,"resolve_sla_minutes":10080,"escalation_chain":[],"create_case":true},"NEUTRAL":{"label":"Neutral","lane":"logged","notify_roles":[],"channels":[],"create_case":false},"POSITIVE":{"label":"Positive","lane":"ready_to_post","notify_roles":[],"channels":[],"create_case":false}}$cfg$::jsonb)
